(* [comment removed for export] *)
Definition PutU (P p0 : Z) (bs : list byte) (mb : byte) (d : pst) (m : mem) : Prop :=
  FieldsC m (P + 80) (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d)
  /\ rw_cells usegs m (P + O_PR_HDR) (HdrCells (ps_h d)) /\ rw_cells usegs m (P + O_PR_USED) [C1 (b8 (ps_u d))]
  /\ MBuf m (P + 168) (ps_es d) (ps_insz d) /\ rw_cells usegs m (P + 232) [C8 (wz (P + 168))]
  /\ rw_cells usegs m (P + 242) [C1 mb] /\ rw_cells usegs m (P + 288) [C8 (wz 0)] /\ rw_cells usegs m (P + 336) [C8 (wz 0)]
  /\ bytes_at usegs m p0 bs /\ PfTab m /\ FTInit m /\ XStatics m.

(* [comment removed for export] *)
Definition PutL (sp : word) (P p0 : Z) (bs : list byte) (LB0 : list block) (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (d : pst) : Prop :=
  let LB := ps_LBn d ++ LB0 in
  pcore_ok (ps_c d)
  /\ FieldsOwn LB (ps_em d) /\ MBufOwn LB (ps_es d) /\ HdrOwnP LB (ps_h d)
  /\ elems_heap (ps_em d)
  /\ (forall x s, In (x, s) (ps_es d) -> 0 < x /\ x + 24 + s <= hceil /\ (x + 24 + s <= 0x10000 \/ 0xb8000 <= x))
  /\ new_elems_off LB0 (bv_unsigned sp) L0 (ps_L d) /\ new_body_off LB0 (bv_unsigned sp) es0 (ps_es d)
  /\ (forall e, e ∈ ps_L d -> e + 48 <= p0 \/ p0 + Z.of_nat (length bs) <= e)
  /\ (forall x s, In (x, s) (ps_es d) -> p0 + Z.of_nat (length bs) <= x \/ x + 24 + s <= p0)
  /\ (forall e x s, e ∈ ps_L d -> In (x, s) (ps_es d) -> e + 48 <= x \/ x + 24 + s <= e)
  /\ (pc_state (ps_c d) <= 1 -> hdr_empty (ps_h d) /\ ps_u d = 0) /\ 0 <= ps_u d <= 1
  /\ mb_cap (ps_es d) <= 3 * ps_insz d + 512 /\ Z.of_nat (length (ps_es d)) <= KB /\ 0 <= ps_insz d
  /\ (pc_state (ps_c d) = 3 \/ pc_state (ps_c d) = 4 \/ pc_state (ps_c d) = 9 -> 1 <= pc_len (ps_c d))
  /\ hdr_disj (ps_L d) (ps_es d) (ps_h d)
  /\ hdr_new LB0 (bv_unsigned sp) h0 (ps_h d)
  /\ (pc_state (ps_c d) < 10 -> pc_hlim (ps_c d) <= 8192) /\ pc_skip (ps_c d) < 2^62
  /\ lbn_ownedP (ps_L d) (ps_h d) (ps_es d) (ps_LBn d)
  /\ lsub L0 (ps_L d) /\ (forall x s, In (x, s) es0 -> In (x, s) (ps_es d)).

(* [comment removed for export] *)
Definition PutB (LB0 : list block) (p0 R : Z) (MX CX : Z) (d : pst) (p : Z) : Prop :=
  lb_bytes (ps_LBn d ++ LB0) + 17 * pc_hlim (ps_c d) + body_res (ps_es d) (ps_insz d) (R - (p - p0))
       + (if pc_state (ps_c d) <=? 9 then 34 else 0) <= MX
  /\ 4 * Z.of_nat (length (ps_LBn d ++ LB0)) + pc_hlim (ps_c d) + 4 * (KB - Z.of_nat (length (ps_es d)))
       + (if pc_state (ps_c d) <=? 1 then 8 else 0) + (if pc_state (ps_c d) <=? 9 then 2 else 0) <= 4 * CX
  /\ ps_insz d + (R - (p - p0)) <= 2^28.

(* [comment removed for export] *)
Lemma pot_if_range : forall st, 0 <= (if st <=? 9 then 34 else 0) <= 34 /\ 0 <= (if st <=? 9 then 2 else 0) <= 2 /\ 0 <= (if st <=? 1 then 8 else 0) <= 8.
Proof. intros st. destruct (st <=? 9); destruct (st <=? 1); lia. Qed.

(* [comment removed for export] *)
Definition put_pure (sp : word) (P E lo : Z) (p0 : Z) (bs : list byte) : Prop :=
  1 <= Z.of_nat (length bs) /\ lo + PUT_STACK <= bv_unsigned sp /\ 0xb8000 <= lo /\ hceil <= lo
  /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0xb8000 <= p0) /\ p0 + Z.of_nat (length bs) <= hceil
  /\ bv_unsigned sp <= P /\ P + 344 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64 /\ (P + 344 <= E \/ E + 24 <= P)
  /\ bv_unsigned sp mod 16 = 0
  /\ E mod 8 = 0.                                                  (* [comment removed for export] *)

