(* [comment removed for export] *)
Lemma elem_client : forall m Fa S L ns ls em LB SP e,
  FieldsC m Fa S L ns ls em -> FieldsOwn LB em -> e ∈ L -> rclient_range LB SP e 48.
Proof.
  intros m Fa S L ns ls em LB SP e FC OWN He.
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & _).
  destruct (proj1 (LEQ e) He) as [d Ld]. destruct (OWN e d Ld) as [p [IN _]]. pose proof (esize_ge d).
  right; right. exists (p, e, esize d). split; [exact IN | cbn; lia].
Qed.

Lemma body_client : forall m b es insz LB SP x s,
  MBuf m b es insz -> MBufOwn LB es -> In (x, s) es -> rclient_range LB SP x (24 + s).
Proof.
  intros m b es insz LB SP x s MB MOWN IN.
  destruct (MOWN x s IN) as [p INb]. pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ.
  pose proof (mb_block_size_range s ltac:(lia)) as [BR _].
  right; right. exists (p, x, mb_block_size s). split; [exact INb | cbn; lia].
Qed.

Lemma cnt_div4 : forall a b c, 0 <= a -> 0 <= b -> 4 * a + b <= 4 * c -> a + b / 4 <= c.
Proof.
  intros a b c Ha Hb Habc. assert (K : b / 4 <= ((c - a) * 4) / 4) by (apply Z.div_le_mono; lia).
  rewrite Z.div_mul in K by lia. lia.
Qed.

Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.
  (* [comment removed for export] *)
  Variables MX CX : Z.

Definition put_static (sp tp : word) (LB0 : list block) (P E lo B p0 R : Z) (bs : list byte) : Prop :=
  put_pure sp P E lo p0 bs
  /\ rclient_range LB0 (bv_unsigned sp) p0 (Z.of_nat (length bs))
  /\ Z.of_nat (length bs) <= R
  /\ bv_unsigned sp <= B /\ P + 344 <= B /\ E + 24 <= B /\ B <= 2^64
  /\ tp = Z_to_bv 64 RATP
  /\ MX <= hs_LIVE_MAX H /\ CX <= hs_LIVE_CNT_MAX H.

(* [comment removed for export] *)
Definition put_post0 (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) : config -> Prop :=
  fun cf => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (d : pst) (q : Z) (E' : ecv),
    cfg_ms cf = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (q - p0)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ hs_KREL H (ps_st d) (cfg_model cf) /\ hs_MPRES H mo0 (cfg_model cf)
    /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' (errno_addr tp) [C4 (ps_errv d)] /\ hs_rauxv_ok H m' B
    /\ hs_RHEAP H (ps_st d) (ps_LBn d ++ LB0) m'
    /\ rw_cells usegs m' P (ParserCoreCells (ps_c d) pad7 pad2)
    /\ rw_cells usegs m' E (ErrCodeCells E') /\ (E' = EC_clear \/ http_fail E')
    /\ rw_cells usegs m' (P + 240) [C1 (ps_rdi d)] /\ HttpCat m' (ps_g d) /\ (FieldTabZero m' \/ FT m')
    /\ PutU P p0 bs mb d m' /\ PutL sp P p0 bs LB0 L0 es0 h0 d /\ PutB LB0 p0 R MX CX d q
    /\ xpres LB0 (bv_unsigned sp) (put_X P E L0 es0) m0 m'
    /\ p0 <= q <= p0 + Z.of_nat (length bs)
    /\ (E' = EC_clear -> p0 < q \/ pc_state (ps_c d) = 11)
    /\ (pc_state (ps_c d) = 11 -> E' = EC_clear).

Definition put_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) : config -> Prop :=
  fun cf => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (d : pst) (q : Z) (E' : ecv),
    cfg_ms cf = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (q - p0)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ hs_KREL H (ps_st d) (cfg_model cf) /\ hs_MPRES H mo0 (cfg_model cf)
    /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' (errno_addr tp) [C4 (ps_errv d)] /\ hs_rauxv_ok H m' B
    /\ hs_RHEAP H (ps_st d) (ps_LBn d ++ LB0) m'
    /\ rw_cells usegs m' P (ParserCoreCells (ps_c d) pad7 pad2)
    /\ rw_cells usegs m' E (ErrCodeCells E') /\ (E' = EC_clear \/ http_fail E')
    /\ rw_cells usegs m' (P + 240) [C1 (ps_rdi d)] /\ HttpCat m' (ps_g d) /\ (FieldTabZero m' \/ FT m')
    /\ PutU P p0 bs mb d m' /\ PutL sp P p0 bs LB0 L0 es0 h0 d /\ PutB LB0 p0 R MX CX d q
    /\ xpres LB0 (bv_unsigned sp) (put_X P E L0 es0) m0 m'
    /\ p0 <= q <= p0 + Z.of_nat (length bs)
    /\ (E' = EC_clear -> p0 < q \/ pc_state (ps_c d) = 11)
    /\ (pc_state (ps_c d) = 11 -> E' = EC_clear)
    /\ HdrOwnP (ps_LBn d ++ LB0) (ps_h d) /\ HdrDisjP (ps_em d) (ps_h d) /\ BodyDisjP (ps_em d) (ps_h d) (ps_es d).

Definition put_stmt : Prop :=
  forall (ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
         (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model) (LB0 : list block)
         (P E lo B : Z) (pad7 pad2 ej : list byte) (p0 R : Z) (bs : list byte) (mb : byte) (d : pst),
  ps_LBn d = [] -> pc_state (ps_c d) <> 11 ->
  rw_cells usegs m P (ParserCoreCells (ps_c d) pad7 pad2) ->
  rw_cells usegs m E [CB 24 ej] ->
  rw_cells usegs m (P + 240) [C1 (ps_rdi d)] -> HttpCat m (ps_g d) -> (FieldTabZero m \/ FT m) ->
  PutU P p0 bs mb d m -> PutL sp P p0 bs LB0 (ps_L d) (ps_es d) (ps_h d) d -> PutB LB0 p0 R MX CX d p0 ->
  put_static sp tp LB0 P E lo B p0 R bs ->
  hs_RHEAP H (ps_st d) LB0 m -> hs_KREL H (ps_st d) mo -> hs_rauxv_ok H m B ->
  stk usegs m lo (bv_unsigned sp) -> rw_cells usegs m (errno_addr tp) [C4 (ps_errv d)] ->
  bv_unsigned mb <= 1 ->             (* [comment removed for export] *)
  mem_inv usegs m ->
  hs_SR H (put_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m mo LB0 P E lo B pad7 pad2 p0 R bs (ps_L d) (ps_es d) (ps_h d) mb)
    (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz p0) (wz (Z.of_nat (length bs))) (wz E) a4 a5 a6 a7
                     s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_BP_PUT) fc None m (seg_rom usegs)) mo).

End SR.
End HCW.
